import { randomUUID } from "node:crypto";
import { DynamoDBClient, GetItemCommand, PutItemCommand } from "@aws-sdk/client-dynamodb";
import { CreateBucketCommand, PutBucketNotificationConfigurationCommand } from "@aws-sdk/client-s3";
import { s3, bucketOf } from "./store.mjs";
import { now, typesOf, writeSpaceMeta } from "./meta.mjs";
import { isReservedSpaceId, isValidSpaceId } from "./ids.mjs";
import { HttpProblem, idConflict, invalidId, invalidRequestBody, reservedId } from "./problems.mjs";

// Creating a Space with a body: what the two routes that do it share.
//
//   POST /spaces/              with a coupon (a registration code): the
//                              Space is an account Space
//   POST /space/{s}/spaces     under an account Space, authorized by a
//                              capability on that Space, with no coupon
//
// Either way the body names the controller, a did:key, and the request is
// signed by that key: a Space is only ever created under a controller that
// signed for it. The id is server-assigned (`dcc-pws-{uuid}`, also the
// bucket name) unless the body names one it may choose. The Space is a
// bucket with its metadata object and a registry row; the row records how
// the Space came to exist (`provisioning`) and, for a Space created under
// an account, which account (`account`, the account Space's registry URL).

const dynamo = new DynamoDBClient({});
const SPACES_TABLE = process.env.SPACES_TABLE_NAME ?? "pws-spaces";
const SPACE_URL_BASE = (process.env.SPACE_URL_BASE ?? "https://was.example.org/space").replace(/\/+$/, "");

// The members of a creation body, validated: the controller (a did:key,
// without any fragment), the optional name, the type array and the id as
// given.
export function spaceRequestOf(body) {
  const { controller, name, id } = body;
  if (typeof controller !== "string" || !controller.startsWith("did:key:")) {
    throw invalidRequestBody('"controller" must be a did:key DID.');
  }
  if (name !== undefined && typeof name !== "string") {
    throw invalidRequestBody('"name" must be a string.');
  }
  return { controller: controller.split("#")[0], name, type: typesOf(body, "Space"), id };
}

async function isRegistered(url) {
  const { Item } = await dynamo.send(new GetItemCommand({ TableName: SPACES_TABLE, Key: { spaceURL: { S: url } } }));
  return Boolean(Item);
}

// The id the Space gets: the client's, when the body names one it may
// choose (a valid id form, not reserved, not in use), else a fresh
// server-assigned one.
export async function chooseSpaceId(id) {
  if (id === undefined) {
    return { spaceId: `dcc-pws-${randomUUID()}`, chosen: false };
  }
  if (typeof id !== "string" || !isValidSpaceId(id)) {
    throw invalidId("A Space id must be a server-assigned id or 43 URL-safe characters.");
  }
  if (isReservedSpaceId(id)) {
    throw reservedId(id);
  }
  if (await isRegistered(`${SPACE_URL_BASE}/${id}`)) {
    throw idConflict("A Space with this id already exists.");
  }
  return { spaceId: id, chosen: true };
}

async function registerSpace({ url, controller, type, name, createdAt, provisioning, account }) {
  try {
    await dynamo.send(
      new PutItemCommand({
        TableName: SPACES_TABLE,
        Item: {
          spaceURL: { S: url },
          did: { S: controller },
          type: { L: type.map((entry) => ({ S: entry })) },
          ...(name !== undefined && { name: { S: name } }),
          CreatedAt: { S: createdAt },
          provisioning: { S: provisioning },
          ...(account !== undefined && { account: { S: account } }),
        },
        ConditionExpression: "attribute_not_exists(spaceURL)",
      })
    );
  } catch (err) {
    if (err?.name === "ConditionalCheckFailedException") {
      throw idConflict("A Space with this id already exists.");
    }
    throw err;
  }
}

// Creates the Space: the bucket, its metadata object and the registry row.
// Two requests racing for one chosen id are caught by the metadata object's
// If-None-Match and by the row's condition. Resolves to the written
// metadata (`doc`, `etag`).
export async function provisionSpace(req, { spaceId, chosen, controller, name, type, provisioning, account }) {
  const stamp = now();
  const doc = {
    id: spaceId,
    type,
    ...(name !== undefined && { name }),
    controller,
    createdBy: controller,
    createdAt: stamp,
    updatedAt: stamp,
  };
  const bucket = bucketOf(spaceId);
  await s3.send(new CreateBucketCommand({ Bucket: bucket }));
  // The bucket's object events feed the Collections' `changes` feeds
  await s3.send(new PutBucketNotificationConfigurationCommand({ Bucket: bucket, NotificationConfiguration: { EventBridgeConfiguration: {} } }));
  let written;
  try {
    written = await writeSpaceMeta(req, spaceId, doc, chosen ? { ifNoneMatch: "*" } : {});
  } catch (err) {
    if (err instanceof HttpProblem && err.status === 412) {
      throw idConflict("A Space with this id already exists.");
    }
    throw err;
  }
  await registerSpace({ url: `${SPACE_URL_BASE}/${spaceId}`, controller, type, name, createdAt: stamp, provisioning, account });
  return written;
}
